item.content:encoded:
/* ===== LIUBC 浅色清爽配色（2026-10-15） ===== */
.main-navigation{background-color:#c9e7cb!important}
.main-navigation ul#primary-menu>li>a{color:#2e5c33!important}
.main-navigation ul#primary-menu>li.current-menu-item>a,.main-navigation ul#primary-menu>li>a:hover,.main-navigation ul#primary-menu>li>a:focus{color:#1b5e20!important}
.broadnews-header .top-header{background-color:#e8f5e9!important}
.top-header{color:#2e5c33!important}
.broadnews-header .top-header .top-bar-left{color:#2e5c33!important}
.top-header .aft-small-social-menu ul li a{font-family:inherit!important;width:auto!important;height:.broadnews-header auto!important;display:inline-block;font-size:13px;font-weight:700;line-height:1.6;padding:4px 12px;margin:2px 0 2px 8px;background-color:#ffffff!important;background-image:none!important;color:#2e5c33!important;border:1px solid #a5d6a7;border-radius:3px;white-space:nowrap;text-transform:none}
.top-header .aft-small-social-menu ul li a:after{display:none!important;content:none!important}
.top-header .aft-small-social-menu ul li a:hover,.top-header .aft-small-social-menu ul li a:focus{color:#1b5e20!important;border-color:#1b5e20!important}
.top-header .aft-small-social-menu .screen-reader-text{clip:auto!important;clip-path:none!important;position:static!important;width:auto!important;height:auto!important;overflow:visible!important}
.site-footer{background-color:#e8f5e9!important}
.site-footer,.site-footer .widget,.site-footer .widget-title,.site-footer a{color:#2e5c33!important}
.site-footer .site-info{background-color:#c8e6c9!important;color:#2e5c33!important}
.site-footer .site-info a{color:#1b5e20!important}
[style*="background-color:#0d1626"],[style*="background-color:#141a24"]{background-color:#e8f5e9!important}
[style*="background-color:#080d16"]{background-color:#f5f5f5!important}
/* ===== 关于我们：手风琴标题加大加粗 + 金色胶囊按钮 ===== */
.page-id-41 .wp-block-details>summary{font-size:21px;font-weight:800}
.page-id-41 .wp-block-details p>a:only-child{display:inline-block;background-color:#c9a24b;color:#141414!important;font-weight:700;font-size:16px;line-height:1.2;padding:13px 34px;border-radius:9999px;text-decoration:none!important;transition:background-color .25s ease,transform .25s ease,box-shadow .25s ease,color .25s ease}
.page-id-41 .wp-block-details p>a:only-child:hover,.page-id-41 .wp-block-details p>a:only-child:focus-visible{background-color:#ddba5f;color:#000!important;transform:translateY(-2px);box-shadow:0 8px 18px rgba(201,162,75,.45)}
.site-footer .aft-small-social-menu ul li:has(>a[href="https://liubc.org/"]),.site-footer .aft-small-social-menu ul li:has(>a[href="https://liubc.org/2026-reading-plan/"]),.site-footer .aft-small-social-menu ul li:has(>a[href="https://liubc.org/about/"]),.site-footer .aft-small-social-menu ul li:has(>a[href="https://liubc.org/contact/"]){display:none}
@media(max-width:992px){.top-header .top-bar-flex{flex-wrap:wrap}.top-header .top-bar-left{flex:1 1 100%;margin-bottom:6px}.top-header .top-bar-right{flex:1 1 100%;justify-content:flex-start;display:flex!important}.top-header .aft-small-social-menu{width:100%}.top-header .aft-small-social-menu ul{display:flex;flex-wrap:nowrap;width:100%;gap:6px;overflow-x:auto}.top-header .aft-small-social-menu ul li{flex:0 0 auto}.top-header .aft-small-social-menu ul li a{display:block;text-align:center;margin:0;padding:7px 10px;font-size:12px}}
/* ===== 全站手风琴（浅色） + CTA 金色按钮 ===== */
.wp-block-details{background:#f7faf7;border:1px solid rgba(46,92,51,.25);border-radius:12px;margin:0 0 14px;overflow:hidden}
.wp-block-details[open]{border-color:#2e5c33;box-shadow:0 4px 18px rgba(46,92,51,.15)}
.wp-block-details>summary{list-style:none;cursor:pointer;color:#2e5c33;font-size:19px;font-weight:700;line-height:1.6;padding:16px 56px 16px 20px;position:relative}
.wp-block-details>summary::-webkit-details-marker{display:none}
.wp-block-details>summary::marker{content:""}
.wp-block-details>summary::after{content:"›";position:absolute;right:20px;top:50%;transform:translateY(-50%) rotate(90deg);color:#2e5c33;font-size:24px;font-weight:700;line-height:1;transition:transform .25s ease}
.wp-block-details[open]>summary::after{transform:translateY(-50%) rotate(-90deg)}
.wp-block-details>summary:hover{color:#1b5e20}
.wp-block-details[open]>summary{border-bottom:1px solid rgba(46,92,51,.2)}
.wp-block-details>:not(summary){color:#333333;font-size:16px;line-height:1.9;padding-left:20px;padding-right:20px}
.wp-block-details>:not(summary):first-of-type{padding-top:14px}
.wp-block-details>:not(summary):last-child{padding-bottom:20px}
.wp-block-details p>a:only-child{display:inline-block;background:#c9a24b;color:#141414!important;font-size:16px;font-weight:700;line-height:1.5;padding:12px 28px;border-radius:999px;text-decoration:none!important;margin:6px 0 4px;transition:background .2s ease,transform .2s ease}
.wp-block-details p>a:only-child:hover,.wp-block-details p>a:only-child:focus{background:#dcbb63;color:#000!important;transform:translateY(-1px)}
.entry-content p>a:only-child:not(:has(img)):not(.post-edit-link):not(.wp-block-button__link),.textwidget>p>a:only-child:not(:has(img)),.textwidget>a:only-child:not(:has(img)){display:inline-block;background:#c9a24b;color:#141414!important;font-size:16px;font-weight:700;line-height:1.5;padding:12px 28px;border-radius:999px;text-decoration:none!important;margin:6px 0;transition:background .2s ease,transform .2s ease}
.entry-content p>a:only-child:not(:has(img)):not(.post-edit-link):not(.wp-block-button__link):hover,.textwidget>p>a:only-child:not(:has(img)):hover,.textwidget>a:only-child:not(:has(img)):hover{background:#dcbb63;color:#000!important;transform:translateY(-1px)}
.liubc-daily-reading a{display:inline-block;background:#c9a24b;color:#141414!important;font-size:15px;font-weight:700;line-height:1.5;padding:10px 24px;border-radius:999px;text-decoration:none!important;margin-top:8px;transition:background .2s ease,transform .2s ease}
.liubc-daily-reading a:hover{background:#dcbb63;color:#000!important;transform:translateY(-1px)}
.entry-content p,.entry-content li{line-height:1.85}
